import math

def calculate_std_dev(numbers: list[float]) -> float | None:
    """
    Calculates the sample standard deviation of a list of numbers.
    Assumes at least two numbers are provided.
    """
    if len(numbers) < 2:
        return None

    n: int = len(numbers)
    mean: float = sum(numbers) / n
    variance: float = sum((x - mean) ** 2 for x in numbers) / (n - 1)
    return math.sqrt(variance)

def process_data(data: list[float | int]) -> float | None:
    """
    Processes a list of mixed float and int data to calculate standard deviation.
    """
    if not data:
        return None

    # Convert all numbers to float for consistent calculation
    float_numbers: list[float] = [float(x) for x in data]
    return calculate_std_dev(float_numbers)

def get_user_input(prompt: str = "Enter numbers separated by spaces: ") -> list[float] | None:
    """
    Gets a list of numbers from user input.
    """
    user_str: str | None = input(prompt)
    if not user_str:
        return None
    try:
        return [float(x) for x in user_str.split()]
    except ValueError:
        print("Invalid input. Please enter numbers only.")
        return None

def main(initial_data: list[float] | None = None) -> None:
    """
    Main function to demonstrate standard deviation calculation.
    """
    if initial_data is None:
        numbers_input: list[float] | None = get_user_input()
        if numbers_input is None or len(numbers_input) < 2:
            print("Not enough numbers to calculate standard deviation.")
            return
        std_dev_result: float | None = calculate_std_dev(numbers_input)
    else:
        std_dev_result: float | None = calculate_std_dev(initial_data)

    if std_dev_result is not None:
        print(f"The sample standard deviation is: {std_dev_result:.3f}")
    else:
        print("Could not calculate standard deviation.")

