def char_frequency(text: str) -> dict[str, int]:
    """
    Counts the frequency of each character in a given string, ignoring case.
    """
    frequency_map: dict[str, int] = {}
    for char in text:
        lower_char: str = char.lower()
        frequency_map[lower_char] = frequency_map.get(lower_char, 0) + 1
    return frequency_map

def _process_string(input_str: str, default_char: str | None = None) -> str:
    if default_char is None:
        return input_str.strip()
    return input_str.replace(' ', default_char).strip()

def _get_char_count(char_map: dict[str, int], char_to_find: str | None = None) -> int | None:
    if char_to_find is None:
        return sum(char_map.values())
    return char_map.get(char_to_find.lower())

def analyze_text_frequency(text: str,
                           process_method: str | None = None,
                           target_char: str | None = None) -> dict[str, int | None] | dict[str, int]:
    processed_text: str = text
    if process_method == "strip":
        processed_text = _process_string(text)
    elif process_method == "replace_space":
        processed_text = _process_string(text, default_char='_')

    freq_map: dict[str, int] = char_frequency(processed_text)

    if target_char is not None:
        count: int | None = _get_char_count(freq_map, target_char)
        return {"target_char_count": count}
    return freq_map

