def parse_log_line(log_line: str | None) -> dict | None:
    if log_line is None:
        return None

    pattern: str = r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) - (INFO|ERROR|WARNING|DEBUG) - (.*)$'
    match: re.Match | None = re.match(pattern, log_line)

    if match:
        timestamp: str | None = match.group(1)
        level: str | None = match.group(2)
        message: str | None = match.group(3)
        return {'timestamp': timestamp, 'level': level, 'message': message}
    else:
        return None

def process_log_data(log_lines: list[str | None]) -> list[dict | None]:
    processed_logs: list[dict | None] = []
    for line in log_lines:
        parsed_log: dict | None = parse_log_line(line)
        processed_logs.append(parsed_log)
    return processed_logs

def get_error_messages(processed_logs: list[dict | None], default_message: str | None = "No error message provided") -> list[str | None]:
    error_messages: list[str | None] = []
    for log_entry in processed_logs:
        if log_entry and log_entry.get('level') == 'ERROR':
            msg: str | None = log_entry.get('message')
            error_messages.append(msg if msg is not None else default_message)
    return error_messages

