def fibonacci_sequence(n: int) -> list[int]:
    """Generates a list of Fibonacci numbers up to n (exclusive)."""
    if n <= 0:
        return []
    elif n == 1:
        return [0]

    fib_list: list[int] = [0, 1]
    a: int | None = 0
    b: int | None = 1

    while True:
        if a is None or b is None:
            break
        next_fib: int | None = a + b
        if next_fib >= n:
            break
        fib_list.append(next_fib)
        a = b
        b = next_fib
    return fib_list

def get_nth_fibonacci(n: int) -> int | None:
    """Returns the nth Fibonacci number."""
    if n < 0:
        return None
    if n == 0:
        return 0
    if n == 1:
        return 1

    a: int | None = 0
    b: int | None = 1
    for _ in range(2, n + 1):
        if a is None or b is None:
            return None
        temp: int | None = a + b
        a = b
        b = temp
    return b

