def parse_url_params(query_string: str) -> Dict[str, str]:
    """
    Parses a URL query string into a dictionary of key-value pairs.
    """
    params: Dict[str, str] = {}
    if not query_string:
        return params

    pairs: List[str] = query_string.split('&')
    for pair in pairs:
        parts: List[str] = pair.split('=', 1)
        key: str | None = parts[0] if parts else None
        value: str | None = parts[1] if len(parts) > 1 else None

        if key is not None and value is not None:
