def calculate_sma(data: list[float | int], window_size: int | None = None) -> list[float | None]:
    if window_size is None or window_size <= 0:
        return []

    sma_values: list[float | None] = []
    n: int | None = len(data)

    if n is None or n < window_size:
        return []

    for i in range(n - window_size + 1):
        current_window: list[float | int] | None = data[i : i + window_size]
        if current_window is not None:
            window_sum: float | None = sum(current_window)
            if window_sum is not None:
                sma: float | None = window_sum / window_size
                sma_values.append(sma)
            else:
                sma_values.append(None)
        else:
            sma_values.append(None)

    return sma_values

