def calculate_power(base: int | float, exponent: int) -> int | float:
    """
    Calculates the result of a base number raised to an exponent.

    Args:
        base: The base number (integer or float).
        exponent: The exponent (integer).

    Returns:
        The result of base^exponent (integer or float).
    """
    if exponent == 0:
        return 1
    elif exponent > 0:
        result: int | float = 1
        for _ in range(exponent):
            result *= base
        return result
    else:  # negative exponent
        positive_exponent: int | None = -exponent
        temp_result: int | float = 1
        if positive_exponent is not None:
            for _ in range(positive_exponent):
                temp_result *= base
        else:
            return 0.0  # Should not happen with valid input
        return 1 / temp_result

