import collections
from typing import List, Optional, Union

def filter_by_length(
    string_list: List[str],
    min_length: int | None = 0,
    max_length: int | None = None,
    prefix: str | None = None,
    suffix: str | None = None,
    case_sensitive: bool = True,
    limit: int | None = None,
) -> List[str]:
    """
    Filters a list of strings based on various criteria.
    """
    filtered_strings: List[str] = []
    current_count: Optional[int] = 0

    for s in string_list:
        string_len: int = len(s)
        is_match: bool = True
        optional_prefix_match: Optional[bool] = None

        if min_length is not None and string_len <= min_length:
            is_match = False

        if max_length is not None and string_len >= max_length:
            is_match = False

        if prefix is not None:
            if case_sensitive:
                optional_prefix_match = s.startswith(prefix)
            else:
                optional_prefix_match = s.lower().startswith(prefix.lower())
            if not optional_prefix_match:
                is_match = False

        optional_suffix_match: Optional[bool] = None
        if suffix is not None:
            if case_sensitive:
                optional_suffix_match = s.endswith(suffix)
            else:
                optional_suffix_match = s.lower().endswith(suffix.lower())
            if not optional_suffix_match:
                is_match = False

        if is_match:
            filtered_strings.append(s)
            if limit is not None:
                current_count = current_count + 1
                if current_count >= limit:
                    break

    return filtered_strings

