class BankAccount:
    def __init__(self, initial_balance: float | int = 0.0) -> None:
        if initial_balance < 0:
            raise ValueError("Initial balance cannot be negative.")
        self._balance: float = float(initial_balance)

    def deposit(self, amount: float | int) -> bool:
        if amount <= 0:
            return False
        self._balance += float(amount)
        return True

    def withdraw(self, amount: float | int) -> bool:
        if amount <= 0 or amount > self._balance:
            return False
        self._balance -= float(amount)
        return True

    def get_balance(self) -> float | int:
        return self._balance

    def transfer(self, target_account: 'BankAccount', amount: float | int) -> bool | None:
        if amount <= 0:
            return False
        if self.withdraw(amount):
            target_account.deposit(amount)
            return True
        return None

    def set_overdraft_limit(self, limit: float | int | None = None) -> None:
        self._overdraft_limit: float | None = float(limit) if limit is not None else None

    def get_overdraft_limit(self) -> float | None:
        return self._overdraft_limit if hasattr(self, '_overdraft_limit') else None

