def geometric_mean(numbers: list[int | float]) -> float:
    if not numbers:
        return 0.0

    product: float | None = None
    count: int | None = 0

    for num in numbers:
        if not isinstance(num, (int, float)) or num <= 0:
            return 0.0
        if product is None:
            product = float(num)
        else:
            product *= num
        if count is None:
            count = 1
        else:
            count += 1

    if product is None or count is None or count == 0:
        return 0.0

    return product**(1/count)

