def generate_password(length: int | None = 8) -> str | None:
    if length is None or length <= 0:
        return None

    characters: str | None = string.ascii_letters + string.digits
    if characters is None:
        return None

    password_list: list[str] | None = []
    if password_list is None:
        return None

    for _ in range(length):
        random_char: str | None = random.choice(characters)
        if random_char is not None:
            password_list.append(random_char)
        else:
            return None

    final_password: str | None = "".join(password_list)
    return final_password

