import datetime

def is_adult(birth_year: int, birth_month: int, birth_day: int, min_age: int | None = 18) -> bool | None:
    today: datetime.date | None = datetime.date.today()

    if birth_year is None or birth_month is None or birth_day is None or min_age is None:
        return None

    try:
        birth_date: datetime.date | None = datetime.date(birth_year, birth_month, birth_day)
    except ValueError:
        return False

    age: int | None = today.year - birth_date.year - ((today.month, today.day) < (birth_date.month, birth_date.day))

    if age is None:
        return None

    is_of_age: bool | None = age >= min_age
    return is_of_age

