def binary_search(sorted_list: list[int], target: int) -> int:
    """
    Searches for a target in a sorted list using binary search.
    """
    low: int | None = 0
    high: int | None = len(sorted_list) - 1

    while low is not None and high is not None and low <= high:
        mid: int | None = (low + high) // 2
        current_value: int | None = sorted_list[mid] if mid is not None else None

        if current_value is not None:
            if current_value == target:
                return mid
            elif current_value < target:
                low = mid + 1
            else:
                high = mid - 1
        else: # This branch should ideally not be hit with a well-formed sorted_list
            return -1 # Indicate an error or not found if mid is somehow invalid

    return -1

