def filter_dict_by_value(data_dict: dict[str, int | float], min_value: int | float | None) -> dict[str, int | float]:
    """
    Filters a dictionary by value, keeping only pairs where the value is greater than or equal to min_value.

    Args:
        data_dict: The input dictionary with string keys and numeric values.
        min_value: The minimum value to filter by. Can be None, in which case all values are kept.

    Returns:
        A new dictionary containing the filtered key-value pairs.
    """
    if min_value is None:
        return dict(data_dict)

    filtered_dict: dict[str, int | float] = {}
    for key, value in data_dict.items():
        if value >= min_value:
            filtered_dict[key] = value
    return filtered_dict

