def reverse_integer(x: int) -> int | None:
    """
    Reverses the digits of an integer, preserving the sign.
    """
    if x is None:
        return None

    sign: int | None = -1 if x < 0 else 1
    abs_x: int | None = abs(x)

    if abs_x is None:
        return None

    s_abs_x: str | None = str(abs_x)
    if s_abs_x is None:
        return None

    reversed_s_abs_x: str | None = s_abs_x[::-1]
    if reversed_s_abs_x is None:
        return None

    reversed_int: int | None = int(reversed_s_abs_x)
    if reversed_int is None:
        return None

    result: int | None = sign * reversed_int
    if result is None:
        return None

    return result

