def justify_text_simple(words: list[str], max_width: int) -> str | None:
    if not words or max_width <= 0:
        return None

    current_line_words: list[str] = []
    lines: list[str] = []
    current_line_length: int | None = 0

    for word in words:
        word_length: int | None = len(word)
        if current_line_words and current_line_length is not None and (current_line_length + 1 + word_length) > max_width:
            lines.append(" ".join(current_line_words))
            current_line_words = [word]
            current_line_length = word_length
        else:
            current_line_words.append(word)
            if current_line_length is not None:
                current_line_length += (1 + word_length) if current_line_words != [word] else word_length
            else:
                current_line_length = word_length

    if current_line_words:
        lines.append(" ".join(current_line_words))

    return "\n".join(lines) if lines else ""

