def add_employee(db: list[dict], employee_id: int, name: str, department: str | None) -> bool:
    """
    Adds a new employee to the database if the employee ID does not already exist.

    Args:
        db: The list of employee dictionaries.
        employee_id: The unique identifier for the employee.
        name: The name of the employee.
        department: The department of the employee.

    Returns:
        True if the employee was added, False otherwise.
    """
    for employee in db:
        if employee.get('id') == employee_id:
            return False

    new_employee: dict[str, int | str | None] = {
        'id': employee_id,
        'name': name,
        'department': department
    }
    db.append(new_employee)
    return True

def find_employee(db: list[dict], employee_id: int) -> dict[str, int | str | None] | None:
    for employee in db:
        if employee.get('id') == employee_id:
            return employee
    return None

def update_employee_department(db: list[dict], employee_id: int, new_department: str | None) -> bool:
    employee = find_employee(db, employee_id)
    if employee:
        employee['department'] = new_department
        return True
    return False

def get_employee_count(db: list[dict]) -> int | None:
    if not db:
        return None
    return len(db)

def remove_employee(db: list[dict], employee_id: int) -> bool:
    initial_length: int | None = get_employee_count(db)
    db[:] = [employee for employee in db if employee.get('id') != employee_id]
    final_length: int | None = get_employee_count(db)
    return initial_length is not None and final_length is not None and initial_length > final_length

