    if log_line is None:
        return None

    match: re.Match[str] | None = re.match(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (.*?): (.*)', log_line)
    if not match:
        return None

    timestamp: str | None = match.group(1) if match.group(1) else None
    level: str | None = match.group(2) if match.group(2) else None
    message: str | None = match.group(3) if match.group(3) else None

    result: Dict[str, Union[str, None]] = {
        'timestamp': timestamp,
        'level': level,
        'message': message
    }
