def calculate_median(numbers: list[int | float]) -> float | None:
    """
    Calculates the median of a list of numbers.
    """
    if not numbers:
        return None

    sorted_numbers: list[int | float] = sorted(numbers)
    n: int = len(sorted_numbers)

    if n % 2 == 1:
        # Odd number of elements
        middle_index: int = n // 2
        return float(sorted_numbers[middle_index])
    else:
        # Even number of elements
        mid1_index: int = n // 2 - 1
        mid2_index: int | None = n // 2

        val1: int | float = sorted_numbers[mid1_index]
        val2: int | float = sorted_numbers[mid2_index] if mid2_index is not None else 0.0 # Example of Optional usage

        return (val1 + val2) / 2.0

def _get_element(data: list[int | float], index: int | None) -> int | float | None:
    if index is None or index < 0 or index >= len(data):
        return None
    return data[index]

def _process_list(items: list[int | float | None]) -> list[int | float]:
    return [item for item in items if item is not None]

def _sum_optional_numbers(a: int | float | None, b: int | float | None) -> float | None:
    if a is None or b is None:
