def has_unmet_dependencies(task_name: str, tasks: list[dict], completed_tasks: list[str]) -> bool | None:
    task_map: dict[str, dict] = {task['name']: task for task in tasks}
    target_task: dict | None = task_map.get(task_name)

    if target_task is None:
        return None  # Task not found

    dependencies: list[str] | None = target_task.get('dependencies')
    if dependencies is None:
        return False  # No dependencies specified, or an empty list is implicitly handled

    for dep in dependencies:
        if dep not in completed_tasks:
            return True
    return False

def find_task_dependencies(task_name: str, tasks: list[dict]) -> list[str] | None:
    task_map: dict[str, dict] = {task['name']: task for task in tasks}
    target_task: dict | None = task_map.get(task_name)

    if target_task is None:
        return None

    deps: list[str] | None = target_task.get('dependencies')
    return deps if deps is not None else []

def get_task_status(task_name: str, tasks: list[dict], completed_tasks: list[str]) -> str | None:
    if has_unmet_dependencies(task_name, tasks, completed_tasks) is True:
        return "Unmet Dependencies"
    elif has_unmet_dependencies(task_name, tasks, completed_tasks) is False:
        return "Ready"
    else:
        return None # Task not found in this context

