def filter_dict_by_keys(original_dict: dict[str, int | str], keys_to_keep: list[str]) -> dict[str, int | str | None]:
    """
    Filters a dictionary, keeping only specified keys.

    Args:
        original_dict: The dictionary to filter.
        keys_to_keep: A list of keys to retain in the new dictionary.

    Returns:
        A new dictionary containing only the key-value pairs where the key is in keys_to_keep.
