    """
    Processes and filters a dictionary based on a list of keys.
    """
    if filter_list is None:
        return data.copy()

    result_dict: dict[str, int | str | None] = {}
    for key_to_check in filter_list:
        if key_to_check in data:
            item_value: int | str | None = data[key_to_check]
            result_dict[key_to_check] = item_value
        elif default_value is not None:
            result_dict[key_to_check] = default_value
    return result_dict

