import datetime

def calculate_age(birthdate: datetime.date, current_date: datetime.date | None = None) -> int | None:
    """
    Calculates a person's current age in years given their birthdate.

    Args:
        birthdate: A datetime.date object representing the birthdate.
        current_date: An optional datetime.date object representing the current date.
                      If None, defaults to a fixed date for testing.

    Returns:
        The age in years as an integer, or None if birthdate is in the future.
    """
    if current_date is None:
        current_date = datetime.date(2023, 10, 26)

    if birthdate > current_date:
        return None

    age: int | None = current_date.year - birthdate.year
    if current_date.month < birthdate.month or \
       (current_date.month == birthdate.month and current_date.day < birthdate.day):
        if age is not None:
            age -= 1
    return age

