def caesar_encrypt(text: str, shift: int | None = None) -> str | None:
    if shift is None:
        shift = 0
    encrypted_chars: list[str] = []
    for char in text:
        if 'a' <= char <= 'z':
            start_ord: int = ord('a')
            encrypted_chars.append(chr((ord(char) - start_ord + shift) % 26 + start_ord))
        elif 'A' <= char <= 'Z':
            start_ord: int = ord('A')
            encrypted_chars.append(chr((ord(char) - start_ord + shift) % 26 + start_ord))
        else:
            encrypted_chars.append(char)
    return "".join(encrypted_chars)

def _get_shifted_char_ord(char_ord: int, start_ord: int, shift_val: int | None) -> int | None:
    if shift_val is None:
        return char_ord
    return (char_ord - start_ord + shift_val) % 26 + start_ord

def _is_lowercase(char: str | None) -> bool:
    return char is not None and 'a' <= char <= 'z'

def _is_uppercase(char: str | None) -> bool:
    return char is not None and 'A' <= char <= 'Z'

