import re
from collections import Counter

def calculate_word_frequency(text: str | None) -> dict[str, int | None]:
    if text is None:
        return {}

    clean_text: str | None = re.sub(r'[^\w\s]', '', text).lower()

    if clean_text is None:
        return {}

    words: list[str] = clean_text.split()

    word_counts: Counter[str] = Counter(words)

    result: dict[str, int | None] = {}
    for word, count in word_counts.items():
        result[word] = count if count > 0 else None

    return result

